"""
Batch robust adaptive denoising for volatile non-stationary time series.

Returned samples are aligned to input indices window_size - 1 through end.
"""
import numpy as np

try:
    from scipy.signal import butter, sosfiltfilt, savgol_filter
except Exception:
    butter = None
    sosfiltfilt = None
    savgol_filter = None

try:
    from scipy.interpolate import PchipInterpolator
except Exception:
    PchipInterpolator = None


def _finite_signal(x):
    z = np.asarray(x, dtype=float).reshape(-1).copy()
    if z.size == 0:
        return z
    good = np.isfinite(z)
    if not np.all(good):
        if np.any(good):
            ind = np.arange(z.size)
            z[~good] = np.interp(ind[~good], ind[good], z[good])
        else:
            z.fill(0.0)
    return z


def _odd_at_most(value, n):
    w = min(int(value), int(n))
    return w if w % 2 else w - 1


def _savgol_safe(x, preferred=11):
    x = _finite_signal(x)
    n = len(x)
    if savgol_filter is None or n < 5:
        return x.copy()
    w = _odd_at_most(preferred, n)
    if w < 5:
        return x.copy()
    try:
        return savgol_filter(x, w, min(3, w - 2), mode="interp")
    except Exception:
        return x.copy()


def _median3(x):
    x = _finite_signal(x)
    if len(x) < 3:
        return x.copy()
    p = np.pad(x, (1, 1), mode="edge")
    return np.median(np.vstack((p[:-2], p[1:-1], p[2:])), axis=0)


def _mad_sigma(x):
    x = np.asarray(x, dtype=float)
    if len(x) == 0:
        return 0.0
    med = np.median(x)
    return float(np.median(np.abs(x - med)) / 0.67448975)


def _spectral_cutoff(x):
    n = len(x)
    if n < 8:
        return 0.18
    power = np.abs(np.fft.rfft(x)) ** 2
    bins = len(power)
    tail = power[max(1, int(0.70 * bins)):]
    floor = float(np.median(tail)) if len(tail) else 0.0
    useful = np.maximum(power - floor, 0.0)
    useful[0] = 0.0
    total = float(np.sum(useful))
    if not np.isfinite(total) or total <= 1e-14:
        return 0.18
    k = int(np.searchsorted(np.cumsum(useful), 0.94 * total))
    k = min(max(k, 1), bins - 1)
    return float(np.clip(2.0 * k / n, 0.07, 0.28))


def _hysteretic_extrema(y, excursion):
    """Alternating extrema confirmed only by a scale-supported reversal."""
    y = np.asarray(y, dtype=float)
    n = len(y)
    if n < 3:
        return np.arange(n, dtype=int)

    excursion = max(float(excursion), 1e-12)
    anchors = [0]

    direction = 1 if y[1] >= y[0] else -1
    candidate = 1

    for i in range(2, n):
        if direction > 0:
            if y[i] >= y[candidate]:
                candidate = i
            elif y[candidate] - y[i] >= excursion:
                if candidate > anchors[-1]:
                    anchors.append(candidate)
                direction = -1
                candidate = i
        else:
            if y[i] <= y[candidate]:
                candidate = i
            elif y[i] - y[candidate] >= excursion:
                if candidate > anchors[-1]:
                    anchors.append(candidate)
                direction = 1
                candidate = i

    if anchors[-1] != n - 1:
        anchors.append(n - 1)

    return np.asarray(anchors, dtype=int)


def _adaptive_full_record_filter(x):
    """Denoise using robust median preconditioning and one low-rank Hankel SVD."""
    x = _finite_signal(x)
    n = len(x)
    if n < 2:
        return x.copy()

    robust = _median3(x)
    if n < 8:
        preliminary = _savgol_safe(robust, 11)
    else:
        width = min(40, max(8, n // 3), n)
        columns = n - width + 1
        try:
            # H[row, column] = robust[row + column]; this orientation makes
            # anti-diagonal averaging recover the original sample indices.
            trajectory = np.lib.stride_tricks.sliding_window_view(
                robust, width
            ).T.astype(float, copy=True)

            u, singular, vt = np.linalg.svd(
                trajectory, full_matrices=False
            )
            energy = singular * singular
            tail = energy[max(1, (2 * len(energy)) // 3):]
            floor = float(np.median(tail)) if len(tail) else 0.0
            useful = np.maximum(energy - floor, 0.0)
            total = float(np.sum(useful))
            if not np.isfinite(total) or total <= 1e-12:
                raise ValueError("degenerate trajectory energy")

            # Stability-selected paired-SSA rank.  Each candidate must retain
            # sufficient de-biased trajectory energy.  The score combines
            # robust slope/detail mismatch, explicit slope-change complexity,
            # and hysteretic false-reversal complexity.
            cumulative = np.cumsum(useful)
            ranks = range(2, min(8, len(singular)) + 1)
            best_rank = None
            best_cost = np.inf
            minimum_energy = 0.92 * total

            for candidate_rank in ranks:
                if cumulative[candidate_rank - 1] < minimum_energy:
                    continue

                candidate_matrix = (
                    u[:, :candidate_rank] *
                    singular[:candidate_rank][None, :]
                ) @ vt[:candidate_rank, :]

                candidate_series = np.zeros(n, dtype=float)
                candidate_counts = np.zeros(n, dtype=float)
                for row in range(width):
                    end = min(columns, n - row)
                    if end:
                        candidate_series[row:row + end] += (
                            candidate_matrix[row, :end]
                        )
                        candidate_counts[row:row + end] += 1.0
                candidate_series /= np.maximum(candidate_counts, 1.0)

                if not np.all(np.isfinite(candidate_series)):
                    continue

                candidate_scale = max(_mad_sigma(candidate_series), 1e-12)
                if n > 2:
                    slope_error = (
                        np.diff(candidate_series, n=2) -
                        np.diff(robust, n=2)
                    )
                    detail_error = (
                        np.diff(candidate_series) - np.diff(robust)
                    )
                    detail_cost = _mad_sigma(detail_error)
                    slope_cost = _mad_sigma(slope_error)
                elif n > 1:
                    detail_cost = _mad_sigma(
                        np.diff(candidate_series) - np.diff(robust)
                    )
                    slope_cost = 0.0
                else:
                    detail_cost = 0.0
                    slope_cost = 0.0

                residual_sigma = _mad_sigma(robust - candidate_series)
                reversal_scale = max(1.2 * residual_sigma, 1e-12)
                reversal_cost = (
                    max(len(_hysteretic_extrema(
                        candidate_series, reversal_scale
                    )) - 2, 0) / max(n, 1)
                )

                # The small rank regularizer resolves nearly equal scores in
                # favor of the lower-complexity reconstruction without
                # materially sacrificing tracking accuracy.
                cost = (
                    detail_cost / candidate_scale
                    + 0.35 * slope_cost / candidate_scale
                    + 2.5 * reversal_cost
                    + 0.002 * candidate_rank
                )

                if np.isfinite(cost) and cost < best_cost:
                    best_cost = cost
                    best_rank = candidate_rank

            if best_rank is None:
                best_rank = min(max(2, 1), 8, len(singular))
            low_rank = (
                u[:, :best_rank] * singular[:best_rank][None, :]
            ) @ vt[:best_rank, :]

            preliminary = np.zeros(n, dtype=float)
            counts = np.zeros(n, dtype=float)
            for row in range(width):
                end = min(columns, n - row)
                if end:
                    preliminary[row:row + end] += low_rank[row, :end]
                    counts[row:row + end] += 1.0
            preliminary /= np.maximum(counts, 1.0)
            preliminary = np.where(
                np.isfinite(preliminary), preliminary, robust
            )
        except Exception:
            preliminary = _savgol_safe(robust, 11)

    if n < 5:
        return preliminary

    # Detect persistent level changes, then reconstruct each level region
    # independently so a global spline cannot ring across a genuine jump.
    residual_sigma = _mad_sigma(x - preliminary)
    signal_scale = _mad_sigma(preliminary)
    noise_floor = max(residual_sigma, 0.015 * signal_scale, 1e-12)
    excursion = max(1.15 * residual_sigma, 0.015 * signal_scale, 1e-12)
    jump_threshold = max(2.5 * residual_sigma, 0.18 * signal_scale, 1e-12)

    candidates = []
    half = 5
    if n >= 2 * half + 2:
        for boundary in range(half, n - half):
            left = preliminary[boundary - half:boundary]
            right = preliminary[boundary:boundary + half]
            left_level = float(np.median(left))
            right_level = float(np.median(right))
            jump = right_level - left_level
            magnitude = abs(jump)
            if magnitude < jump_threshold:
                continue

            # Reject ramps and oscillatory crossings: each side must contain
            # at least three samples close to its own robust level.
            tolerance = max(0.35 * magnitude, 2.0 * noise_floor)
            left_close = np.abs(left - left_level) <= tolerance
            right_close = np.abs(right - right_level) <= tolerance
            if np.count_nonzero(left_close) < 3:
                continue
            if np.count_nonzero(right_close) < 3:
                continue

            # Confirm that the jump direction is consistent immediately around
            # the boundary rather than being caused by a single overshoot.
            left_tail = preliminary[boundary - 3:boundary]
            right_head = preliminary[boundary:boundary + 3]
            if jump > 0:
                if np.count_nonzero(left_tail <= left_level + tolerance) < 2:
                    continue
                if np.count_nonzero(right_head >= right_level - tolerance) < 2:
                    continue
            else:
                if np.count_nonzero(left_tail >= left_level - tolerance) < 2:
                    continue
                if np.count_nonzero(right_head <= right_level + tolerance) < 2:
                    continue
            candidates.append((boundary, magnitude))

    # Keep only well-separated boundaries and limit topology complexity.
    merged = []
    for boundary, strength in candidates:
        if merged and boundary - merged[-1][0] < 7:
            if strength > merged[-1][1]:
                merged[-1] = (boundary, strength)
        else:
            merged.append((boundary, strength))
    merged = merged[:23]
    cuts = [0] + [item[0] for item in merged] + [n]

    noise_ratio = residual_sigma / max(signal_scale, 1e-12)
    skeleton_weight = float(np.clip(
        0.84 + 0.10 * noise_ratio, 0.84, 0.94
    ))
    skeleton = preliminary.copy()

    for start, stop in zip(cuts[:-1], cuts[1:]):
        if stop - start < 7:
            continue
        part = preliminary[start:stop]
        local_scale = max(_mad_sigma(part), 0.015 * signal_scale, 1e-12)
        anchors = _hysteretic_extrema(part, max(excursion, local_scale))
        if len(anchors) < 3:
            continue
        try:
            if PchipInterpolator is None:
                raise ValueError("no pchip")
            local = PchipInterpolator(
                anchors, part[anchors], extrapolate=True
            )(np.arange(stop - start))
        except Exception:
            local = np.interp(
                np.arange(stop - start), anchors, part[anchors]
            )
        local = np.asarray(local, dtype=float)
        local = np.where(np.isfinite(local), local, part)
        skeleton[start:stop] = (
            skeleton_weight * local
            + (1.0 - skeleton_weight) * part
        )

    # Preserve sharp accepted jumps.  Only smooth the join when the two
    # neighboring reconstructed values do not retain the detected jump.
    for boundary, strength in merged:
        if boundary < 2 or boundary + 1 >= n:
            continue
        reconstructed_jump = abs(
            skeleton[boundary] - skeleton[boundary - 1]
        )
        if reconstructed_jump < 0.5 * strength:
            midpoint = 0.5 * (
                skeleton[boundary - 1] + skeleton[boundary]
            )
            skeleton[boundary - 1] = 0.75 * skeleton[boundary - 1] + 0.25 * midpoint
            skeleton[boundary] = 0.25 * midpoint + 0.75 * skeleton[boundary]

    skeleton = np.asarray(skeleton, dtype=float)
    skeleton = np.where(np.isfinite(skeleton), skeleton, preliminary)
    return np.where(np.isfinite(skeleton), skeleton, preliminary)


def adaptive_filter(x, window_size=20):
    """Apply Hankel low-rank denoising followed by hysteretic trend projection."""
    x = _finite_signal(x)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    return _adaptive_full_record_filter(x)[window_size - 1:]


def enhanced_filter_with_trend_preservation(x, window_size=20):
    return adaptive_filter(x, window_size)


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    return enhanced_filter_with_trend_preservation(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2.0 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2.0 * t)
        + 0.5 * np.sin(2 * np.pi * 5.0 * t)
        + 0.8 * np.exp(-t / 5.0) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(rng.randn(length) * 0.05)
    noisy_signal = clean_signal + rng.normal(0, noise_level, length)
    return noisy_signal, clean_signal


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(
            signal_length, noise_level
        )
    else:
        noisy_signal = _finite_signal(noisy_signal)
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")

    if clean_signal is None:
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered_signal),
        }

    aligned_clean = clean_signal[window_size - 1:]
    aligned_noisy = noisy_signal[window_size - 1:]
    m = min(len(filtered_signal), len(aligned_clean))
    filtered_signal = filtered_signal[:m]
    aligned_clean = aligned_clean[:m]
    aligned_noisy = aligned_noisy[:m]

    correlation = (
        float(np.corrcoef(filtered_signal, aligned_clean)[0, 1])
        if m > 1 and np.std(filtered_signal) > 0 and np.std(aligned_clean) > 0
        else 0.0
    )
    noise_before = np.var(aligned_noisy - aligned_clean)
    noise_after = np.var(filtered_signal - aligned_clean)
    noise_reduction = (
        float((noise_before - noise_after) / noise_before)
        if noise_before > 0 else 0.0
    )

    return {
        "filtered_signal": filtered_signal,
        "clean_signal": aligned_clean,
        "noisy_signal": aligned_noisy,
        "correlation": correlation,
        "noise_reduction": noise_reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")
